import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent {
  activeFolder = 'inbox';
  mobileListVisible = false;

  onFolderChange(folder: string): void {
    this.activeFolder = folder;
    this.mobileListVisible = true;
  }

  onEmailSelected(): void {

  }
}
<div class="app-shell">
  <app-sidebar (folderChange)="onFolderChange($event)"></app-sidebar>

  <main class="app-main">
    <app-email-list [folder]="activeFolder" (emailSelected)="onEmailSelected()"></app-email-list>
    <app-email-preview class="app-preview"></app-email-preview>
  </main>
</div>
